template <template <typename, typename> class Ser>
class Json {
 public:
  template <typename T, typename U = T>
  Json(T&& val) noexcept(noexcept(Ser<U>::to_json(*this, val))) {
    Ser<U>::to_json(*this, val);
  }
  void Reserve(int n) throw(std::bad_alloc) {}
};
